triggersBlock.example:
triggers {
    timer(hour: 7, minute: 0, daysOfWeek: WEEKDAYS) as morning;
    shakeDevice() when (screenOnOff(screenOn: true));
}

constraintsBlock.example:
constraints {
    dayOfWeek(daysOfWeek: WEEKDAYS);
    batteryLevel(greaterThan: true, batteryLevel: 20) || externalPower(externalPower: true);
}
